 /**
+* Orca patch: marker columns are counted without the delimiter, so trim() left later sibling tasks indented and
+* parseIndentedBlocks cut into them. Dedent by the first task; a task one column deeper is a sibling, and other
+* text at or within the first task's column stays nested under the task above.
+*/
+function dedentOrderedItemTaskBlock(blockLines) {
+	const isTaskLine = (line) => /^\s*[-+*]\s+\[[ xX]\][^\S\r\n]/.test(line);
+	const leadingWidth = (line) => line.length - line.trimStart().length;
+	const firstIndex = blockLines.findIndex((line) => line.trim() !== "");
+	if (firstIndex === -1 || !isTaskLine(blockLines[firstIndex])) return null;
+	const firstIndent = leadingWidth(blockLines[firstIndex]);
+	return blockLines.slice(firstIndex).map((line) => {
+		if (line.trim() === "") return "";
+		const indent = leadingWidth(line);
+		const depth = indent - firstIndent;
+		if (isTaskLine(line)) return depth === 1 ? line.trimStart() : line.slice(Math.min(indent, firstIndent));
+		if (depth > 0) return depth === 1 ? ` ${line.slice(firstIndent)}` : line.slice(firstIndent);
+		return indent > 0 ? `  ${line.trimStart()}` : line;
+	}).join("\n").trimEnd();
+}
+/**
 * Recursively builds a nested structure from a flat array of list items
 * based on their indentation levels. Creates proper markdown tokens with
 * nested lists where appropriate.
